import java.io.*;
import java.util.*;

public final class Main {

    static PrintWriter out = new PrintWriter(System.out);
    static FastReader in = new FastReader();
    static Pair[] moves = new Pair[]{new Pair(-1, 0), new Pair(0, 1), new Pair(1, 0), new Pair(0, -1)};
    static int mod = (int) (1e9 + 7);
    static int mod2 = 998244353;

    public static void main(String[] args) {
        int tt = 1;
        while (tt-- > 0) {
            solve();
        }
        out.flush();
    }

    public static void solve() {
        int n = i();
        double p = d();

        int l = 0;
        int r = n - 1;
        while (l < r) {
            int m = (l + r) / 2;
            double x = cal(m, n);
            if (x >= p) {
                r = m;
            } else {
                l = m + 1;
            }
        }
        out.println(l);
    }

    private static double cal(int m, int n) {
        long ttl = comb(n, 3);
        double ans = 0d;
        ans += 1d * (comb(m, 3));
        ans += 1d * (comb(m, 2) * comb(n - m, 1));
        ans += 0.5 * (comb(m, 1) * comb(n - m, 2));
        return ans / ttl;
    }

    private static long comb(int n, int c) {
        if (c > n) {
            return 0;
        }
        if (c == n) {
            return 1;
        }
        long ans = 1L;
        for (int i = 0; i < c; i++) {
            ans *= (n - i);
        }
        for (int i = 1; i <= c; i++) {
            ans /= i;
        }
        return ans;
    }

    static long[] pre(int[] a) {
